const WORK_STATE_START = "<!-- fugue-work-state";
const COORDINATOR_START = "<!-- fugue-coordinator-snapshot";
const RECOVERY_START = "<!-- fugue-durable-recovery";
const WORK_ROLLOVER_START = "<!-- fugue-work-rollover";
const END = "-->";
const WORK_RECEIPT = "Fugue-Authority-Receipt: work-d3";
const COORDINATOR_RECEIPT = "Fugue-Authority-Receipt: coordinator-d3";
const DURABLE_PREFIX = "fugue/d3/";
const AUTHORITY_KEY_PREFIX = "Fugue-Authority-Key: ";
const AUTHORITY_COMMIT_PREFIX = "Fugue-Authority-Commit: ";
const SECRET_BYTES = 16;
const SECRET_HEX_LENGTH = SECRET_BYTES * 2;
const REDACTED_SECRET = "0".repeat(SECRET_HEX_LENGTH);
const DURABLE_CHUNK_SIZE = 100;
const DURABLE_MAX_CHUNKS = 48;
const DURABLE_WRITE_ATTEMPTS = 4;
const REPOSITORY_AUTHORITY_VARIABLE_CAPACITY = 500;
const AUTHORITY_VARIABLE_PAGE_SIZE = 100;
const RECOVERY_READ_BUILD_ATTEMPTS = 2;
const RECOVERY_AUTHORITY_PREFIX = "FUGUE_D3_";
const RECOVERY_PACK_PREFIX = "FUGUE_D3P_";
const RECOVERY_RESERVE_PREFIX = "FUGUE_D3R_";
const RECOVERY_MUTATION_GUARD_PREFIX = "FUGUE_D3GT_";
const RECOVERY_MUTATION_GUARD_IDLE = "FUGUE_D3GI_00";
const RECOVERY_MUTATION_GUARD_IDLE_VALUE = "reserved-for-fugue-recovery-mutation-guard";
const RECOVERY_MUTATION_GUARD_GRACE_MS = 10 * 60 * 1000;
const RECOVERY_RESERVE_COUNT = 8;
const RECOVERY_RESERVE_VALUE = "reserved-for-fugue-recovery-compaction";
const RECOVERY_PACK_MAX_ENTRIES = 17;
const RECOVERY_PACK_VALUE_LIMIT = 44 * 1024;
const WORK_ROLLOVER_SCOPE = "work-rollover";
const WORK_ROLLOVER_PAGE_SIZE = 100;
const WORK_ROLLOVER_AUTHORITY_PREFIX = "rollover-v1:";
const MANIFEST_PATTERN = /^n=(\d+);c=([0-9a-f]{32});b=([0-9a-f]{64});a=(\d+);z=(\d+)$/i;
const DURABLE_MANIFEST_URL = "https://token.actions.githubusercontent.com/fugue/d3";
const WORK_AUTHORITY_PREFIX = "work-v2:";

const stateLabelSchema = z.enum(["state:ready", "state:working", "state:blocked"]);
const canonicalPrSchema = z.object({ number: z.number().int().positive(), metadata: prMetadataSchema, draft: z.boolean() });

export const canonicalWorkStateSchema = z.object({
  version: z.literal(1), kind: z.literal("work_state"), issue: z.number().int().positive(), title: z.string().min(1),
  state: stateLabelSchema, agent_ready: z.boolean(), requirements_b64: z.string(), metadata: workMetadataSchema,
  pr: canonicalPrSchema.nullable(), base_sha: z.string().regex(/^[0-9a-f]{40}$/i), created_at: z.string().min(1),
  authority_sequence: z.number().int().nonnegative().optional(),
  parent_digest: z.string().regex(/^sha256:[0-9a-f]{64}$/i).nullable().optional(),
  coordinator_issue_updated_at: z.string().min(1).optional(),
  coordinator_event_sequence: z.number().int().nonnegative().optional(),
  coordinator_event_id: z.string().min(1).optional(),
}).superRefine((value, context) => {
  const coordinatorFields = [value.coordinator_issue_updated_at, value.coordinator_event_sequence, value.coordinator_event_id]
    .filter((field) => field !== undefined).length;
  if (coordinatorFields !== 0 && coordinatorFields !== 3) {
    context.addIssue({ code: z.ZodIssueCode.custom, message: "Canonical work-state Coordinator identity must be complete." });
  }
});

export const coordinatorSnapshotSchema = z.object({
  version: z.literal(1), kind: z.literal("coordinator_snapshot"), event_id: z.string().min(1),
  event_sequence: z.number().int().nonnegative().default(0), event_name: z.literal("issues"), action: z.string().min(1),
  actor: z.string().min(1), issue: z.number().int().positive(), label: z.string().optional(), title: z.string(), body: z.string(),
  labels: z.array(z.string()), issue_updated_at: z.string().min(1), captured_at: z.string().min(1),
});

const workRolloverProgressSchema = z.object({
  version: z.literal(1), kind: z.literal("work_rollover_progress"), base_sha: z.string().regex(/^[0-9a-f]{40}$/i),
  page: z.number().int().positive(), complete: z.boolean(), created_at: z.string().min(1),
});

const recoveryManifestSchema = z.object({
  id: z.number().int().positive(), key: z.string().regex(/^[0-9a-f]{32}$/i), nonce: z.string().regex(/^[0-9a-f]{32}$/i),
  body_digest: z.string().regex(/^[0-9a-f]{64}$/i), authority_order_b64: z.string().min(1), first_status_id: z.number().int().positive(),
  last_status_id: z.number().int().positive(), chunk_count: z.number().int().positive().max(DURABLE_MAX_CHUNKS),
  status_ids: z.array(z.number().int().positive()).min(1).max(DURABLE_MAX_CHUNKS), proof: z.string().min(1).optional(),
  created_at: z.string().min(1).optional(),
});

const recoveryCursorSchema = z.object({
  version: z.literal(1), kind: z.literal("durable_recovery"), scope: z.string().min(1),
  storage_sha: z.string().regex(/^[0-9a-f]{40}$/i), publisher_sha: z.string().regex(/^[0-9a-f]{40}$/i),
  checkpoint_at: z.string().min(1).default("1970-01-01T00:00:00.000Z"), complete_top_id: z.number().int().nonnegative(),
  scan_top_id: z.number().int().nonnegative(), scan_floor_id: z.number().int().nonnegative(), before_id: z.number().int().positive(),
  page: z.number().int().positive(), phase: z.enum(["discover", "materialize"]), commit_witness: z.boolean().default(false),
  best_body_b64: z.string().optional(), best_manifest: recoveryManifestSchema.optional(),
  chunks: z.array(z.string().nullable()).max(DURABLE_MAX_CHUNKS).optional(),
});

const recoveryPackSchema = z.object({ version: z.literal(1), kind: z.literal("durable_recovery_pack"), entries: z.array(z.string().min(1)).min(1).max(RECOVERY_PACK_MAX_ENTRIES) });

export type CanonicalWorkState = z.infer<typeof canonicalWorkStateSchema>;
export type CanonicalPrState = z.infer<typeof canonicalPrSchema>;
export type CoordinatorSnapshot = z.infer<typeof coordinatorSnapshotSchema>;
type WorkRolloverProgress = z.infer<typeof workRolloverProgressSchema>;
type RecoveryCursor = z.infer<typeof recoveryCursorSchema>;

export class CanonicalWorkStateIntegrityError extends Error { constructor(message: string) { super(message); this.name = "CanonicalWorkStateIntegrityError"; } }
export class DurableProtocolRecoveryPendingError extends Error { constructor(message: string) { super(message); this.name = "DurableProtocolRecoveryPendingError"; } }
class RecoveryReadEpochChangedError extends DurableProtocolRecoveryPendingError { constructor(message: string) { super(message); this.name = "RecoveryReadEpochChangedError"; } }

export interface WorkPrState { number: number; url: string; headSha: string; headBranch: string; draft: boolean; metadata: PrMetadata; }
export interface WorkState {
  issueNumber: number; title: string; url: string; stateLabel: "state:ready" | "state:working" | "state:blocked"; agentReady: boolean;
  metadata: WorkMetadata; requirements: string; workSpecDigest: string; pr: WorkPrState | null; drift: string[]; presentationDrift: string[]; canonical: CanonicalWorkState;
}
export interface RepositoryState { policy: ActivePolicy; works: WorkState[]; drift: string[]; }
interface DurableBundleRecord { context: string; description: string; }
export interface DurableRecord<T> { value: T; body: string; }
export interface DurableRecoveryResult<T> { record?: DurableRecord<T>; exhausted: boolean; }
export interface DurableRecordOptions<T> {
  storageSha: string; publisherSha: string; scope: string; issueNumber: number; parse: (body: string) => T | null;
  timestamp: (value: T) => number; order: (value: T) => string; compare?: (left: T, right: T) => number; validate?: (value: T) => boolean;
}

export function createCanonicalWorkState(input: {
  issue: number; title: string; state: WorkState["stateLabel"]; agentReady: boolean; requirements: string; metadata: WorkMetadata;
  pr?: CanonicalPrState | null; baseSha: string; createdAt?: string; predecessor?: CanonicalWorkState; logicalRoot?: boolean;
  coordinator?: { issueUpdatedAt: string; eventSequence: number; eventId: string };
}): CanonicalWorkState {
  assertWorkMetadataForIssue(input.metadata, input.issue);
  const predecessor = input.predecessor ? canonicalWorkStateSchema.parse(input.predecessor) : undefined;
  if (predecessor && (predecessor.issue !== input.issue || predecessor.base_sha.toLowerCase() !== input.baseSha.toLowerCase())) throw new CanonicalWorkStateIntegrityError("Canonical work-state predecessor does not match the proposed issue/base identity.");
  if (predecessor && input.logicalRoot) throw new CanonicalWorkStateIntegrityError("Canonical work-state publication cannot be both a logical root and a successor.");
  const authoritySequence = predecessor ? (predecessor.authority_sequence ?? -1) + 1 : input.logicalRoot ? 0 : undefined;
  const parentDigest = predecessor ? canonicalWorkStateDigest(predecessor) : input.logicalRoot ? null : undefined;
  const inheritedCoordinator = predecessor?.coordinator_issue_updated_at !== undefined && predecessor.coordinator_event_sequence !== undefined && predecessor.coordinator_event_id !== undefined
    ? { issueUpdatedAt: predecessor.coordinator_issue_updated_at, eventSequence: predecessor.coordinator_event_sequence, eventId: predecessor.coordinator_event_id } : undefined;
  const coordinator = input.coordinator ?? inheritedCoordinator;
  return canonicalWorkStateSchema.parse({
    version: 1, kind: "work_state", issue: input.issue, title: input.title, state: input.state, agent_ready: input.agentReady,
    requirements_b64: Buffer.from(input.requirements, "utf8").toString("base64url"), metadata: input.metadata, pr: input.pr ?? null,
    base_sha: input.baseSha, created_at: input.createdAt ?? new Date().toISOString(),
    ...(authoritySequence === undefined ? {} : { authority_sequence: authoritySequence, parent_digest: parentDigest }),
    ...(coordinator ? { coordinator_issue_updated_at: coordinator.issueUpdatedAt, coordinator_event_sequence: coordinator.eventSequence, coordinator_event_id: coordinator.eventId } : {}),
  });
}

function canonicalWorkStateDigest(state: CanonicalWorkState): string { return `sha256:${createHash("sha256").update(JSON.stringify(canonicalWorkStateSchema.parse(state)), "utf8").digest("hex")}`; }
function canonicalWorkAuthorityOrder(state: CanonicalWorkState): string { return state.authority_sequence === undefined ? state.created_at : `${WORK_AUTHORITY_PREFIX}${String(state.authority_sequence).padStart(20, "0")}`; }
export function canonicalRequirements(state: CanonicalWorkState): string { try { return Buffer.from(state.requirements_b64, "base64url").toString("utf8"); } catch { throw new Error(`Canonical work state for Issue #${state.issue} has invalid requirements encoding.`); } }
export function serializeCanonicalWorkState(state: CanonicalWorkState): string { const payload = Buffer.from(JSON.stringify(canonicalWorkStateSchema.parse(state)), "utf8").toString("base64url"); return `${WORK_STATE_START}\nversion: 1\npayload: ${payload}\n${END}`; }
export function parseCanonicalWorkState(body: string): CanonicalWorkState | null { return parsePayloadBlock(body, WORK_STATE_START, canonicalWorkStateSchema, (parsed) => { assertWorkMetadataForIssue(parsed.metadata, parsed.issue); canonicalRequirements(parsed); }); }
export function serializeCoordinatorSnapshot(snapshot: CoordinatorSnapshot): string { const payload = Buffer.from(JSON.stringify(coordinatorSnapshotSchema.parse(snapshot)), "utf8").toString("base64url"); return `${COORDINATOR_START}\nversion: 1\npayload: ${payload}\n${END}`; }
export function parseCoordinatorSnapshot(body: string): CoordinatorSnapshot | null { return parsePayloadBlock(body, COORDINATOR_START, coordinatorSnapshotSchema); }
function serializeWorkRolloverProgress(progress: WorkRolloverProgress): string { const payload = Buffer.from(JSON.stringify(workRolloverProgressSchema.parse(progress)), "utf8").toString("base64url"); return `${WORK_ROLLOVER_START}\nversion: 1\npayload: ${payload}\n${END}`; }
function parseWorkRolloverProgress(body: string): WorkRolloverProgress | null { return parsePayloadBlock(body, WORK_ROLLOVER_START, workRolloverProgressSchema); }

export function sameCanonicalWorkState(left: CanonicalWorkState, right: CanonicalWorkState): boolean {
  return left.issue === right.issue && left.base_sha.toLowerCase() === right.base_sha.toLowerCase() && left.title === right.title && left.state === right.state &&
    left.agent_ready === right.agent_ready && left.requirements_b64 === right.requirements_b64 && JSON.stringify(left.metadata) === JSON.stringify(right.metadata) &&
    JSON.stringify(left.pr) === JSON.stringify(right.pr) && left.coordinator_issue_updated_at === right.coordinator_issue_updated_at &&
    left.coordinator_event_sequence === right.coordinator_event_sequence && left.coordinator_event_id === right.coordinator_event_id;
}
function exactCanonicalWorkState(left: CanonicalWorkState, right: CanonicalWorkState): boolean { return sameCanonicalWorkState(left, right) && left.created_at === right.created_at && left.authority_sequence === right.authority_sequence && left.parent_digest === right.parent_digest; }

function durablePrefix(scope: string): string { if (!/^[A-Za-z0-9._/-]{1,56}$/.test(scope)) throw new Error(`Invalid durable Fugue scope ${scope}.`); return `${DURABLE_PREFIX}${scope}`; }
export function durableDataContext(scope: string, bundleKey: string, index: number): string { const digest = createHmac("sha256", Buffer.from(bundleKey, "hex")).update(String(index), "utf8").digest("hex").slice(0, 24); return `${durablePrefix(scope)}/d/${digest}`; }
export function durableManifestContext(scope: string, bundleKey: string): string { return `${durablePrefix(scope)}/m/${bundleKey}`; }
function authorityBody(unsignedBody: string, key: string, nonce: string): string { return `${unsignedBody}\n\n${AUTHORITY_KEY_PREFIX}${key}\n${AUTHORITY_COMMIT_PREFIX}${nonce}`; }
function logicalAuthorityBody(signedBody: string): string { const marker = `\n\n${AUTHORITY_KEY_PREFIX}`; const index = signedBody.lastIndexOf(marker); return index < 0 ? signedBody : signedBody.slice(0, index); }
function redactAuthorityBody(signedBody: string, key: string, nonce: string): string { const keyLine = `${AUTHORITY_KEY_PREFIX}${key}`; const commitLine = `${AUTHORITY_COMMIT_PREFIX}${nonce}`; if (!signedBody.includes(keyLine) || !signedBody.includes(commitLine)) throw new Error("Signed durable body does not contain its authority capability."); return signedBody.replace(keyLine, `${AUTHORITY_KEY_PREFIX}${REDACTED_SECRET}`).replace(commitLine, `${AUTHORITY_COMMIT_PREFIX}${REDACTED_SECRET}`); }
function restoreAuthorityBody(redactedBody: string, key: string, nonce: string): string | null { const keyLine = `${AUTHORITY_KEY_PREFIX}${REDACTED_SECRET}`; const commitLine = `${AUTHORITY_COMMIT_PREFIX}${REDACTED_SECRET}`; if (!redactedBody.includes(keyLine) || !redactedBody.includes(commitLine)) return null; return redactedBody.replace(keyLine, `${AUTHORITY_KEY_PREFIX}${key}`).replace(commitLine, `${AUTHORITY_COMMIT_PREFIX}${nonce}`); }
function encodeDurableBundle(scope: string, key: string, nonce: string, signedBody: string): { data: DurableBundleRecord[]; manifest: DurableBundleRecord } {
  const redacted = redactAuthorityBody(signedBody, key, nonce); const encoded = gzipSync(Buffer.from(redacted, "utf8")).toString("base64url"); const chunks: string[] = [];
  for (let offset = 0; offset < encoded.length; offset += DURABLE_CHUNK_SIZE) chunks.push(encoded.slice(offset, offset + DURABLE_CHUNK_SIZE));
  if (!chunks.length || chunks.length > DURABLE_MAX_CHUNKS) throw new Error(`Durable Fugue record requires unsupported chunk count ${chunks.length}.`);
  const digest = createHash("sha256").update(encoded, "utf8").digest("hex");
  return { data: chunks.map((chunk, index) => ({ context: durableDataContext(scope, key, index), description: chunk })), manifest: { context: durableManifestContext(scope, key), description: `n=${chunks.length};d=${digest};c=${nonce}` } };
}

export async function publishDurableProtocolRecord(github: FugueGitHub, input: { storageSha: string; publisherSha: string; scope: string; unsignedBody: string; publicationTimestamp: number; authorityOrder: string }): Promise<string> {
  const { owner, repo } = github.repository; let lastError: unknown;
  for (let attempt = 0; attempt < DURABLE_WRITE_ATTEMPTS; attempt += 1) {
    const key = randomBytes(SECRET_BYTES).toString("hex"); const nonce = randomBytes(SECRET_BYTES).toString("hex");
    try {
      await assertRepositoryDefaultBranchRevision(github, input.publisherSha);
      const signedBody = await signProtocolBody(github, authorityBody(input.unsignedBody, key, nonce));
      if (!(await verifyProtocolPublicationBodyAtRevision(github, signedBody, input.publisherSha, input.publicationTimestamp))) throw new Error("Protected publisher proof does not match the exact durable-record revision.");
      const bundle = encodeDurableBundle(input.scope, key, nonce, signedBody); const writtenIds: number[] = [];
      for (const record of bundle.data) { const response = await github.octokit.rest.repos.createCommitStatus({ owner, repo, sha: input.storageSha, state: "success", context: record.context, description: record.description }); writtenIds.push(response.data.id); }
      if (!writtenIds.length) throw new Error("Durable record wrote no data chunks.");
      await assertRepositoryDefaultBranchRevision(github, input.publisherSha);
      if (!(await verifyProtocolPublicationBodyAtRevision(github, signedBody, input.publisherSha, input.publicationTimestamp))) throw new Error("Protected publisher identity changed before durable authority commit.");
      const firstStatusId = Math.min(...writtenIds); const lastStatusId = Math.max(...writtenIds); const bodyDigest = createHash("sha256").update(signedBody, "utf8").digest("hex");
      const manifestBinding = { storageSha: input.storageSha, scope: input.scope, key, nonce, bodyDigest, authorityOrder: input.authorityOrder, firstStatusId, lastStatusId, chunkCount: bundle.data.length, statusIds: writtenIds };
      const manifestProof = await createDurableManifestProof(github, manifestBinding); const manifestTarget = durableManifestTargetUrl(input.authorityOrder, manifestProof, writtenIds);
      await assertRepositoryDefaultBranchRevision(github, input.publisherSha);
      const manifestResponse = await github.octokit.rest.repos.createCommitStatus({ owner, repo, sha: input.storageSha, state: "success", context: bundle.manifest.context, description: `n=${bundle.data.length};c=${nonce};b=${bodyDigest};a=${firstStatusId};z=${lastStatusId}`, target_url: manifestTarget });
      await assertRepositoryDefaultBranchRevision(github, input.publisherSha);
      const committedManifest = recoveryManifestSchema.parse({ id: manifestResponse.data.id, key, nonce, body_digest: bodyDigest, authority_order_b64: Buffer.from(input.authorityOrder, "utf8").toString("base64url"), first_status_id: firstStatusId, last_status_id: lastStatusId, chunk_count: bundle.data.length, status_ids: writtenIds, proof: manifestProof, created_at: manifestResponse.data.created_at });
      const recoveryIdentityOptions: RecoveryIdentityOptions = { storageSha: input.storageSha, publisherSha: input.publisherSha, scope: input.scope };
      const previous = await findRecoveryCursorForPublisher(github, recoveryIdentityOptions); let bestManifest = committedManifest; let bestSignedBody = signedBody;
      if (previous?.cursor.commit_witness && previous.cursor.best_manifest && previous.cursor.best_body_b64) {
        const previousSignedBody = Buffer.from(previous.cursor.best_body_b64, "base64url").toString("utf8"); const manifestComparison = compareManifest(previous.cursor.best_manifest, committedManifest);
        if (manifestComparison > 0) { bestManifest = previous.cursor.best_manifest; bestSignedBody = previousSignedBody; }
        else if (manifestComparison === 0) { if (logicalAuthorityBody(previousSignedBody) !== input.unsignedBody) throw new CanonicalWorkStateIntegrityError(`Conflicting protected durable bodies share authority order ${input.authorityOrder}.`); bestManifest = previous.cursor.best_manifest; bestSignedBody = previousSignedBody; }
      }
      const completeTopId = Math.max(previous?.cursor.complete_top_id ?? 0, committedManifest.id);
      await writeRecoveryCursor(github, recoveryIdentityOptions, recoveryCursorSchema.parse({ version: 1, kind: "durable_recovery", scope: input.scope, storage_sha: input.storageSha, publisher_sha: input.publisherSha, complete_top_id: completeTopId, scan_top_id: completeTopId, scan_floor_id: completeTopId, before_id: completeTopId + 1, page: 1, phase: "discover", commit_witness: true, best_body_b64: Buffer.from(bestSignedBody, "utf8").toString("base64url"), best_manifest: bestManifest }));
      const durable = await findRecoveryCursorForPublisher(github, recoveryIdentityOptions);
      if (!durable?.cursor.commit_witness || !durable.cursor.best_body_b64) throw new CanonicalWorkStateIntegrityError(`Protected durable witness for ${input.scope} did not become readable.`);
      return Buffer.from(durable.cursor.best_body_b64, "base64url").toString("utf8");
    } catch (error) { if (httpStatus(error) !== 422) throw error; lastError = error; await assertRepositoryDefaultBranchRevision(github, input.publisherSha); }
  }
  throw new Error(`Unable to commit a fresh durable Fugue record: ${message(lastError)}`);
}

export async function recoverDurableProtocolRecord<T>(github: FugueGitHub, options: DurableRecordOptions<T>): Promise<DurableRecoveryResult<T>> {
  return withRecoveryReadSession(github, async (session) => {
    const inspected = await inspectRecoveryIdentity(github, options, session);
    if (inspected.uncertain) { await assertRecoveryReadEpoch(github, session.epoch); invalidateRecoveryReadSession(github); throw new DurableProtocolRecoveryPendingError(`Protected durable commit witness for ${options.scope} exists but is not currently verifiable.`); }
    const cursor = inspected.best?.cursor;
    if (!cursor?.commit_witness || !cursor.best_body_b64 || !cursor.best_manifest) { await assertRecoveryReadEpoch(github, session.epoch); if (inspected.structural) { invalidateRecoveryReadSession(github); throw new DurableProtocolRecoveryPendingError(`Protected durable commit witness for ${options.scope} exists but is not currently verifiable.`); } return { exhausted: true }; }
    const body = Buffer.from(cursor.best_body_b64, "base64url").toString("utf8"); const value = await validateDurableBody(github, options, body); await assertRecoveryReadEpoch(github, session.epoch);
    if (!value || options.order(value) !== manifestOrder(cursor.best_manifest)) throw new CanonicalWorkStateIntegrityError(`Protected durable commit witness for ${options.scope} failed body/order validation.`);
    return { record: { value, body }, exhausted: true };
  });
}

async function validateDurableBody<T>(github: FugueGitHub, options: DurableRecordOptions<T>, body: string): Promise<T | undefined> { let value: T | null; try { value = options.parse(body); } catch { return undefined; } if (!value || (options.validate && !options.validate(value))) return undefined; const timestamp = options.timestamp(value); if (!Number.isFinite(timestamp)) return undefined; try { if (!(await verifyProtocolPublicationBodyAtRevision(github, body, options.publisherSha, timestamp))) return undefined; } catch { return undefined; } return value; }
function compareDurable<T>(options: DurableRecordOptions<T>, left: T, right: T): number { return options.compare?.(left, right) ?? options.timestamp(left) - options.timestamp(right); }

interface RecoveryManifest { id: number; key: string; nonce: string; body_digest: string; authority_order_b64: string; first_status_id: number; last_status_id: number; chunk_count: number; status_ids: number[]; }
function encodeStatusIds(ids: readonly number[]): string { let previous = 0; return ids.map((id, index) => { const value = index === 0 ? id : id - previous; previous = id; return value.toString(36); }).join("."); }
function decodeStatusIds(value: string): number[] | undefined { if (!value || value.length > 512) return undefined; const parts = value.split("."); if (!parts.length || parts.length > DURABLE_MAX_CHUNKS) return undefined; const ids: number[] = []; let previous = 0; for (let index = 0; index < parts.length; index += 1) { const part = parts[index]; if (!part || !/^[0-9a-z]+$/i.test(part)) return undefined; const encoded = Number.parseInt(part, 36); if (!Number.isSafeInteger(encoded) || encoded <= 0) return undefined; const id = index === 0 ? encoded : previous + encoded; if (!Number.isSafeInteger(id) || id <= previous) return undefined; ids.push(id); previous = id; } return ids; }
function durableManifestTargetUrl(order: string, proof: string, statusIds: readonly number[]): string { const target = new URL(DURABLE_MANIFEST_URL); target.searchParams.set("o", Buffer.from(order, "utf8").toString("base64url")); target.searchParams.set("i", encodeStatusIds(statusIds)); target.searchParams.set("p", proof); return target.toString(); }
function parseDurableManifestTarget(value: string): { order: string; proof: string; statusIds: number[] } | undefined { try { const target = new URL(value); if (`${target.origin}${target.pathname}` !== DURABLE_MANIFEST_URL) return undefined; const encodedOrder = target.searchParams.get("o"); const encodedIds = target.searchParams.get("i"); const proof = target.searchParams.get("p"); if (!encodedOrder || !encodedIds || !proof) return undefined; const order = Buffer.from(encodedOrder, "base64url").toString("utf8"); const statusIds = decodeStatusIds(encodedIds); if (!order || order.length > 512 || !statusIds) return undefined; return { order, proof, statusIds }; } catch { return undefined; } }
function manifestOrder(manifest: RecoveryManifest): string { return Buffer.from(manifest.authority_order_b64, "base64url").toString("utf8"); }
function compareManifest(left: RecoveryManifest, right: RecoveryManifest): number { return compareAuthorityOrder(manifestOrder(left), manifestOrder(right)); }
function compareAuthorityOrder(left: string, right: string): number { return left < right ? -1 : left > right ? 1 : 0; }

interface FugueAuthorityVariable { name: string; value: string; }
interface RecoveryReadSession { epoch: string; variables: readonly FugueAuthorityVariable[]; }
interface LocalRecoveryMutationSettlement { guardName: string; settled: Promise<void>; resolve: () => void; }
