async function recentIssueComments(github: FugueGitHub, issueNumber: number) { const { owner, repo } = github.repository; const issue = await github.octokit.rest.issues.get({ owner, repo, issue_number: issueNumber }); const total = issue.data.comments ?? 0; const page = Math.max(1, Math.ceil(total / 100)); const response = await github.octokit.rest.issues.listComments({ owner, repo, issue_number: issueNumber, per_page: 100, page }); return response.data; }
async function deleteCommentIfPresent(github: FugueGitHub, commentId: number): Promise<void> { const { owner, repo } = github.repository; try { await github.octokit.rest.issues.deleteComment({ owner, repo, comment_id: commentId }); } catch (error) { if (httpStatus(error) !== 404) throw error; } }
async function deleteTrustedReceiptComments(github: FugueGitHub, issueNumber: number, receipt: string): Promise<void> { for (const comment of await recentIssueComments(github, issueNumber)) { if (!(comment.body ?? "").includes(receipt)) continue; if (!(await isTrustedProtocolComment(github, comment))) continue; await deleteCommentIfPresent(github, comment.id); } }
async function loadWorkLocator(github: FugueGitHub, issueNumber: number, baseSha: string): Promise<CanonicalWorkState | undefined> { const matches: CanonicalWorkState[] = []; for (const comment of await recentIssueComments(github, issueNumber)) { const body = comment.body ?? ""; if (!body.includes(WORK_RECEIPT) || !(await isTrustedProtocolComment(github, comment))) continue; let parsed: CanonicalWorkState | null; try { parsed = parseCanonicalWorkState(body); } catch { continue; } if (!parsed || parsed.issue !== issueNumber || parsed.base_sha.toLowerCase() !== baseSha.toLowerCase()) continue; matches.push(parsed); } if (!matches.length) return undefined; const newest = matches.sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at)).at(-1)!; if (matches.some((candidate) => !exactCanonicalWorkState(candidate, newest))) return undefined; return newest; }
async function createWorkLocator(github: FugueGitHub, state: CanonicalWorkState): Promise<void> { await createProtocolComment(github, state.issue, `${renderCanonicalWorkStateComment(state)}\n\n${WORK_RECEIPT}`); }
export async function publishCanonicalWorkState(github: FugueGitHub, state: CanonicalWorkState): Promise<boolean> { let parsed = canonicalWorkStateSchema.parse(state); assertWorkMetadataForIssue(parsed.metadata, parsed.issue); const current = await loadCurrentCanonicalWorkState(github, parsed.issue, parsed.base_sha); if (current && sameCanonicalWorkState(current, parsed)) return false; const logical = parsed.authority_sequence !== undefined; if (logical !== (parsed.parent_digest !== undefined)) throw new CanonicalWorkStateIntegrityError("Logical canonical work state must carry both authority sequence and parent digest."); if (logical) { if (current) { const expectedSequence = (current.authority_sequence ?? -1) + 1; if (parsed.authority_sequence !== expectedSequence || parsed.parent_digest !== canonicalWorkStateDigest(current)) return false; } else if (parsed.authority_sequence !== 0 || parsed.parent_digest !== null) return false; } else if (current?.authority_sequence !== undefined) return false; await assertRepositoryDefaultBranchRevision(github, parsed.base_sha); const requestedCreated = Date.parse(parsed.created_at); if (!Number.isFinite(requestedCreated)) throw new CanonicalWorkStateIntegrityError("Canonical work state has an invalid publication timestamp."); if (!logical) { const minimumCreated = current ? Date.parse(current.created_at) + 1 : 0; parsed = canonicalWorkStateSchema.parse({ ...parsed, created_at: new Date(Math.max(Date.now(), minimumCreated, requestedCreated)).toISOString() }); } const committedBody = await publishDurableProtocolRecord(github, { storageSha: parsed.base_sha, publisherSha: parsed.base_sha, scope: workScope(parsed.issue), unsignedBody: renderCanonicalWorkStateComment(parsed), publicationTimestamp: Date.parse(parsed.created_at), authorityOrder: canonicalWorkAuthorityOrder(parsed) }); const committed = parseCanonicalWorkState(committedBody); if (!committed || committed.issue !== parsed.issue || committed.base_sha.toLowerCase() !== parsed.base_sha.toLowerCase()) throw new CanonicalWorkStateIntegrityError(`Protected durable work-state publication for Issue #${parsed.issue} returned another identity.`); await replaceWorkLocator(github, committed); return exactCanonicalWorkState(committed, parsed); }
export async function loadCurrentCanonicalWorkState(github: FugueGitHub, issueNumber: number, baseSha: string): Promise<CanonicalWorkState | undefined> { const recovered = await recoverWorkStateAtBase(github, issueNumber, baseSha); if (recovered.record) { await replaceWorkLocator(github, recovered.record.value); return recovered.record.value; } if (recovered.exhausted) return undefined; throw new DurableProtocolRecoveryPendingError(`Issue #${issueNumber} canonical work-state recovery is progressing through bounded status history.`); }
async function replaceWorkLocator(github: FugueGitHub, state: CanonicalWorkState): Promise<void> { const locator = await loadWorkLocator(github, state.issue, state.base_sha); if (locator && exactCanonicalWorkState(locator, state)) return; await deleteTrustedReceiptComments(github, state.issue, WORK_RECEIPT); await createWorkLocator(github, state); }
async function recoverWorkStateAtBase(github: FugueGitHub, issueNumber: number, baseSha: string): Promise<DurableRecoveryResult<CanonicalWorkState>> { return recoverDurableProtocolRecord(github, { storageSha: baseSha, publisherSha: baseSha, scope: workScope(issueNumber), issueNumber, parse: parseCanonicalWorkState, timestamp: (value) => Date.parse(value.created_at), order: canonicalWorkAuthorityOrder, validate: (value) => value.issue === issueNumber && value.base_sha.toLowerCase() === baseSha.toLowerCase() }); }
function workScope(issueNumber: number): string { return `work/${issueNumber}`; }
function structuralWorkWitnesses(variables: readonly FugueAuthorityVariable[]): { currentByIssue: Map<string, Set<number>>; historicalBySha: Map<string, Set<number>> } { const currentByIssue = new Map<string, Set<number>>(); const historicalBySha = new Map<string, Set<number>>(); for (const body of recoveryBodiesFromVariables(variables)) { const cursor = parseRecoveryCursorBody(body); const issue = cursor?.scope.match(/^work\/(\d+)$/)?.[1]; if (!cursor?.commit_witness || !issue || cursor.storage_sha.toLowerCase() !== cursor.publisher_sha.toLowerCase()) continue; const issueNumber = Number.parseInt(issue, 10); if (!Number.isSafeInteger(issueNumber) || issueNumber <= 0) continue; const sha = cursor.storage_sha.toLowerCase(); const issues = historicalBySha.get(sha) ?? new Set<number>(); issues.add(issueNumber); historicalBySha.set(sha, issues); const currentIssues = currentByIssue.get(sha) ?? new Set<number>(); currentIssues.add(issueNumber); currentByIssue.set(sha, currentIssues); } return { currentByIssue, historicalBySha }; }
export async function loadReusableCanonicalWorkState(github: FugueGitHub, issueNumber: number, currentBaseSha: string, _baseBranch: string, historyPage = 1): Promise<CanonicalWorkState | undefined> { const session = await getRecoveryReadSession(github); const { historicalBySha } = structuralWorkWitnesses(session.variables); const relevant = new Set([...historicalBySha.entries()].filter(([sha, issues]) => sha !== currentBaseSha.toLowerCase() && issues.has(issueNumber)).map(([sha]) => sha)); if (!relevant.size) { await assertRecoveryReadEpoch(github, session.epoch); return undefined; } const { owner, repo } = github.repository; const response = await github.octokit.rest.repos.listCommits({ owner, repo, sha: currentBaseSha, per_page: WORK_ROLLOVER_PAGE_SIZE, page: historyPage }); for (const commit of response.data) { const sha = commit.sha.toLowerCase(); if (!relevant.has(sha)) continue; const recovered = await recoverWorkStateAtBase(github, issueNumber, sha); if (recovered.record) return recovered.record.value; } await assertRecoveryReadEpoch(github, session.epoch); return undefined; }
function workRolloverAuthorityOrder(progress: WorkRolloverProgress): string { return `${WORK_ROLLOVER_AUTHORITY_PREFIX}${String(progress.page).padStart(10, "0")}:${progress.complete ? "1" : "0"}:${progress.created_at}`; }
async function recoverWorkRolloverProgress(github: FugueGitHub, baseSha: string): Promise<WorkRolloverProgress | undefined> { const recovered = await recoverDurableProtocolRecord(github, { storageSha: baseSha, publisherSha: baseSha, scope: WORK_ROLLOVER_SCOPE, issueNumber: 1, parse: parseWorkRolloverProgress, timestamp: (value) => Date.parse(value.created_at), order: workRolloverAuthorityOrder, validate: (value) => value.base_sha.toLowerCase() === baseSha.toLowerCase() }); return recovered.record?.value; }
async function publishWorkRolloverProgress(github: FugueGitHub, baseSha: string, page: number, complete: boolean): Promise<void> { const progress = workRolloverProgressSchema.parse({ version: 1, kind: "work_rollover_progress", base_sha: baseSha, page, complete, created_at: new Date().toISOString() }); await publishDurableProtocolRecord(github, { storageSha: baseSha, publisherSha: baseSha, scope: WORK_ROLLOVER_SCOPE, unsignedBody: serializeWorkRolloverProgress(progress), publicationTimestamp: Date.parse(progress.created_at), authorityOrder: workRolloverAuthorityOrder(progress) }); }
export async function rollCanonicalWorkStatesToCurrentBase(github: FugueGitHub, policy: ActivePolicy): Promise<number[]> { const session = await getRecoveryReadSession(github); const currentSha = policy.identity.baseSha.toLowerCase(); const { currentByIssue, historicalBySha } = structuralWorkWitnesses(session.variables); historicalBySha.delete(currentSha); const progress = await recoverWorkRolloverProgress(github, policy.identity.baseSha); if (progress?.complete) return []; const page = progress?.page ?? 1; if (!historicalBySha.size) { await assertRecoveryReadEpoch(github, session.epoch); await publishWorkRolloverProgress(github, policy.identity.baseSha, page, true); return []; } const { owner, repo } = github.repository; const response = await github.octokit.rest.repos.listCommits({ owner, repo, sha: policy.identity.baseSha, per_page: WORK_ROLLOVER_PAGE_SIZE, page }); for (const commit of response.data) { const sha = commit.sha.toLowerCase(); const issueNumbers = historicalBySha.get(sha); if (!issueNumbers) continue; for (const issueNumber of [...issueNumbers].sort((left, right) => left - right)) { if (currentByIssue.get(currentSha)?.has(issueNumber)) { try { if (await loadCurrentCanonicalWorkState(github, issueNumber, policy.identity.baseSha)) continue; } catch (error) { if (error instanceof DurableProtocolRecoveryPendingError) return []; throw error; } } let previous: CanonicalWorkState | undefined; try { previous = (await recoverWorkStateAtBase(github, issueNumber, sha)).record?.value; } catch (error) { if (error instanceof DurableProtocolRecoveryPendingError) return []; throw error; } if (!previous) continue; const next = createCanonicalWorkState({ issue: previous.issue, title: previous.title, state: previous.state, agentReady: previous.agent_ready, requirements: canonicalRequirements(previous), metadata: previous.metadata, pr: previous.pr, baseSha: policy.identity.baseSha, logicalRoot: true }); if (await publishCanonicalWorkState(github, next)) return [issueNumber]; return []; } } await assertRecoveryReadEpoch(github, session.epoch); const complete = response.data.length < WORK_ROLLOVER_PAGE_SIZE; await publishWorkRolloverProgress(github, policy.identity.baseSha, complete ? page : page + 1, complete); return []; }

export async function repairCanonicalWorkStateComments(github: FugueGitHub, policy: ActivePolicy): Promise<number[]> { const { owner, repo } = github.repository; const issues = await github.octokit.paginate(github.octokit.rest.issues.listForRepo, { owner, repo, state: "all", per_page: 100 }); const repaired: number[] = []; for (const issue of issues) { if (issue.pull_request) continue; try { const before = await loadWorkLocator(github, issue.number, policy.identity.baseSha); const state = await loadCurrentCanonicalWorkState(github, issue.number, policy.identity.baseSha); if (!before && state) repaired.push(issue.number); } catch (error) { if (!(error instanceof DurableProtocolRecoveryPendingError)) throw error; } } return repaired; }
function renderCanonicalWorkStateComment(state: CanonicalWorkState): string { return `${serializeCanonicalWorkState(state)}\n\nFUGUE WORK STATE — CANONICAL\n\nWork: \`${state.metadata.work_id}\`\nIssue: #${state.issue}`; }
export async function publishCoordinatorSnapshot(github: FugueGitHub, baseSha: string, snapshot: CoordinatorSnapshot): Promise<void> { const parsed = coordinatorSnapshotSchema.parse(snapshot); const current = await loadLatestCoordinatorSnapshot(github, parsed.issue, baseSha); if (current && compareCoordinatorSnapshots(parsed, current) <= 0) return; const committedBody = await publishDurableProtocolRecord(github, { storageSha: baseSha, publisherSha: baseSha, scope: coordinatorScope(parsed.issue), unsignedBody: `${serializeCoordinatorSnapshot(parsed)}\n\nCOORDINATOR SNAPSHOT — DURABLE`, publicationTimestamp: Date.parse(parsed.captured_at), authorityOrder: coordinatorAuthorityOrder(parsed) }); const committed = parseCoordinatorSnapshot(committedBody); if (!committed || committed.issue !== parsed.issue) throw new CanonicalWorkStateIntegrityError(`Protected durable Coordinator publication for Issue #${parsed.issue} returned another identity.`); await replaceCoordinatorLocator(github, committed); }
export async function loadLatestCoordinatorSnapshot(github: FugueGitHub, issueNumber: number, baseSha: string): Promise<CoordinatorSnapshot | undefined> { const recovered = await recoverDurableProtocolRecord(github, { storageSha: baseSha, publisherSha: baseSha, scope: coordinatorScope(issueNumber), issueNumber, parse: parseCoordinatorSnapshot, timestamp: (value) => Date.parse(value.captured_at), order: coordinatorAuthorityOrder, compare: compareCoordinatorSnapshots, validate: (value) => value.issue === issueNumber }); if (recovered.record) { await replaceCoordinatorLocator(github, recovered.record.value); return recovered.record.value; } if (recovered.exhausted) return undefined; throw new DurableProtocolRecoveryPendingError(`Issue #${issueNumber} Coordinator snapshot recovery is progressing through bounded status history.`); }
async function replaceCoordinatorLocator(github: FugueGitHub, snapshot: CoordinatorSnapshot): Promise<void> { const locator = await loadCoordinatorLocator(github, snapshot.issue); if (locator && compareCoordinatorSnapshots(locator, snapshot) === 0) return; await deleteTrustedReceiptComments(github, snapshot.issue, COORDINATOR_RECEIPT); await createProtocolComment(github, snapshot.issue, `${serializeCoordinatorSnapshot(snapshot)}\n\nCOORDINATOR SNAPSHOT — DURABLE\n\n${COORDINATOR_RECEIPT}`); }
export async function recoverCoordinatorSnapshots(github: FugueGitHub, policy: ActivePolicy): Promise<CoordinatorSnapshot[]> { const { owner, repo } = github.repository; const issues = await github.octokit.paginate(github.octokit.rest.issues.listForRepo, { owner, repo, state: "open", per_page: 100 }); const snapshots: CoordinatorSnapshot[] = []; for (const issue of issues) { if (issue.pull_request) continue; try { const snapshot = await loadLatestCoordinatorSnapshot(github, issue.number, policy.identity.baseSha); if (snapshot) snapshots.push(snapshot); } catch (error) { if (!(error instanceof DurableProtocolRecoveryPendingError)) throw error; } } return snapshots; }
async function loadCoordinatorLocator(github: FugueGitHub, issueNumber: number): Promise<CoordinatorSnapshot | undefined> { const matches: CoordinatorSnapshot[] = []; for (const comment of await recentIssueComments(github, issueNumber)) { const body = comment.body ?? ""; if (!body.includes(COORDINATOR_RECEIPT) || !(await isTrustedProtocolComment(github, comment))) continue; let parsed: CoordinatorSnapshot | null; try { parsed = parseCoordinatorSnapshot(body); } catch { continue; } if (parsed?.issue === issueNumber) matches.push(parsed); } return matches.sort(compareCoordinatorSnapshots).at(-1); }
export function compareCoordinatorSnapshots(left: CoordinatorSnapshot, right: CoordinatorSnapshot): number { return compareAuthorityOrder(coordinatorAuthorityOrder(left), coordinatorAuthorityOrder(right)); }
function coordinatorAuthorityOrder(snapshot: CoordinatorSnapshot): string { return `${snapshot.issue_updated_at}\u0000${String(snapshot.event_sequence).padStart(20, "0")}\u0000${snapshot.event_id}`; }
function coordinatorScope(issueNumber: number): string { return `coord/${issueNumber}`; }

export async function reconstructState(github: FugueGitHub): Promise<RepositoryState> {
  const policy = await resolveActivePolicy(github); const { owner, repo } = github.repository;
  const [issues, pulls] = await Promise.all([github.octokit.paginate(github.octokit.rest.issues.listForRepo, { owner, repo, state: "all", per_page: 100 }), github.octokit.paginate(github.octokit.rest.pulls.list, { owner, repo, state: "all", per_page: 100 })]);
  const pullsByNumber = new Map(pulls.map((pull) => [pull.number, pull] as const)); const repositoryDrift: string[] = []; const works: WorkState[] = [];
  for (const issue of issues) {
    if (issue.pull_request) continue; let canonical: CanonicalWorkState | undefined;
    try { canonical = await loadCurrentCanonicalWorkState(github, issue.number, policy.identity.baseSha); } catch (error) { if (error instanceof DurableProtocolRecoveryPendingError) { repositoryDrift.push(`Issue #${issue.number}: bounded canonical work-state recovery is in progress`); continue; } throw error; }
    if (!canonical) { const body = issue.body ?? ""; const looksManaged = body.includes("<!-- fugue-work") || issue.labels.map(labelName).some((label) => label === "state:ready" || label === "state:working" || label === "state:blocked" || label === "agent:ready"); if (looksManaged) repositoryDrift.push(`Issue #${issue.number}: presentation state exists without a current protected canonical work-state authority`); continue; }
    const requirements = canonicalRequirements(canonical); const drift: string[] = []; const presentationDrift: string[] = []; const body = issue.body ?? ""; let mirrorMetadata: WorkMetadata | null = null;
    try { mirrorMetadata = parseWorkMetadata(body); } catch (error) { presentationDrift.push(`issue fugue-work mirror is malformed (${message(error)})`); }
    if (!mirrorMetadata || JSON.stringify(mirrorMetadata) !== JSON.stringify(canonical.metadata)) presentationDrift.push("issue fugue-work mirror differs from canonical state");
    try { if (stripWorkMetadata(body) !== requirements) presentationDrift.push("issue requirements mirror differs from canonical state"); } catch { presentationDrift.push("issue requirements mirror is malformed"); }
    if (issue.title !== canonical.title) presentationDrift.push("issue title mirror differs from canonical state");
    const stateLabels = issue.labels.map(labelName).filter((name): name is WorkState["stateLabel"] => name === "state:ready" || name === "state:working" || name === "state:blocked");
    if (stateLabels.length !== 1 || stateLabels[0] !== canonical.state) presentationDrift.push("issue lifecycle label mirror differs from canonical state");
    const agentReadyMirror = issue.labels.map(labelName).includes("agent:ready"); if (agentReadyMirror !== canonical.agent_ready) presentationDrift.push("issue agent:ready mirror differs from canonical state");
    let pr: WorkPrState | null = null;
    if (canonical.pr) { const pull = pullsByNumber.get(canonical.pr.number); if (!pull) drift.push(`canonical PR #${canonical.pr.number} is not visible`); else { if (pull.state !== "open") { const detail = await github.octokit.rest.pulls.get({ owner, repo, pull_number: pull.number }); if (detail.data.merged) continue; presentationDrift.push(`canonical PR #${pull.number} is closed`); } if (pull.base.ref !== policy.identity.baseBranch) presentationDrift.push(`PR #${pull.number} base differs from protected base`); if (pull.head.ref !== canonical.pr.metadata.branch) drift.push(`PR #${pull.number} head differs from canonical branch`); let mirrorPr: PrMetadata | null = null; try { mirrorPr = parsePrMetadata(pull.body); } catch (error) { presentationDrift.push(`PR #${pull.number} fugue-pr mirror is malformed (${message(error)})`); } if (!mirrorPr || !samePrMetadata(mirrorPr, canonical.pr.metadata)) presentationDrift.push(`PR #${pull.number} fugue-pr mirror differs from canonical state`); if ((pull.draft ?? false) !== canonical.pr.draft) presentationDrift.push(`PR #${pull.number} draft mirror differs from canonical state`); pr = { number: pull.number, url: pull.html_url, headSha: pull.head.sha, headBranch: pull.head.ref, draft: canonical.pr.draft, metadata: canonical.pr.metadata }; } }
    if (issue.state !== "open") presentationDrift.push("issue is closed while canonical work remains active");
    works.push({ issueNumber: issue.number, title: canonical.title, url: issue.html_url, stateLabel: canonical.state, agentReady: canonical.agent_ready, metadata: canonical.metadata, requirements, workSpecDigest: workSpecDigestFromRequirements(requirements, canonical.metadata), pr, drift, presentationDrift, canonical });
  }
  assertAcyclicDependencies(works.map((work) => ({ issueNumber: work.issueNumber, dependencies: work.metadata.spec.dependencies })));
  const activeManagedIssues = new Set(works.map((work) => work.issueNumber)); const dependencyCache = new Map<number, string | null>();
  for (const work of works) for (const dependency of work.metadata.spec.dependencies) { if (activeManagedIssues.has(dependency)) continue; let problem = dependencyCache.get(dependency); if (problem === undefined) { const canonicalDependency = await loadCurrentCanonicalWorkState(github, dependency, policy.identity.baseSha); if (!canonicalDependency) problem = "has no current protected canonical Fugue work state"; else if (!canonicalDependency.pr) problem = "has no protected canonical PR linkage"; else { try { const pull = await github.octokit.rest.pulls.get({ owner, repo, pull_number: canonicalDependency.pr.number }); if (pull.data.head.ref !== canonicalDependency.pr.metadata.branch) problem = `canonical PR #${canonicalDependency.pr.number} no longer matches its protected branch identity`; else if (!pull.data.merged) problem = `canonical PR #${canonicalDependency.pr.number} is not merged`; else problem = null; } catch (error) { if (isNotFound(error)) problem = `canonical PR #${canonicalDependency.pr.number} does not exist`; else throw error; } } dependencyCache.set(dependency, problem); } if (problem) work.drift.push(`dependency #${dependency} ${problem}`); }
  return { policy, works: works.sort((a, b) => a.issueNumber - b.issueNumber), drift: repositoryDrift };
}

function parsePayloadBlock<T>(body: string, startMarker: string, schema: z.ZodType<T>, afterParse?: (value: T) => void): T | null { const start = body.indexOf(startMarker); if (start < 0) return null; const end = body.indexOf(END, start + startMarker.length); if (end < 0) throw new Error(`Unterminated ${startMarker.slice(5)} block.`); const block = body.slice(start + startMarker.length, end).trim(); const match = block.match(/^version: 1\npayload: ([A-Za-z0-9_-]+)$/); if (!match?.[1]) throw new Error(`Malformed ${startMarker.slice(5)} block.`); let raw: unknown; try { raw = JSON.parse(Buffer.from(match[1], "base64url").toString("utf8")) as unknown; } catch { throw new Error(`Invalid ${startMarker.slice(5)} payload.`); } const parsed = schema.parse(raw); afterParse?.(parsed); return parsed; }
function labelName(label: string | { name?: string | null }): string { return typeof label === "string" ? label : label.name ?? ""; }
function isNotFound(error: unknown): boolean { return typeof error === "object" && error !== null && "status" in error && (error as { status?: number }).status === 404; }
function httpStatus(error: unknown): number | undefined { if (!error || typeof error !== "object" || !("status" in error)) return undefined; const status = (error as { status?: unknown }).status; return typeof status === "number" ? status : undefined; }
function escapeRegex(value: string): string { return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"); }
function message(error: unknown): string { return error instanceof Error ? error.message : String(error); }
